public struct Board: Sendable, Equatable {
    public static let width = 10
    public static let height = 20

    public private(set) var rows: [[Bool]]

    public init() {
        rows = Array(repeating: Array(repeating: false, count: Board.width), count: Board.height)
    }

    public var highestFilledRow: Int {
        rows.firstIndex(where: { $0.contains(true) })!
    }

    public mutating func fill(row: Int, column: Int) {
        rows[row][column] = true
    }

    public mutating func clearFullRows() -> Int {
        let kept = rows.filter { $0.contains(false) }
        let cleared = rows.count - kept.count
        rows = Array(repeating: Array(repeating: false, count: Board.width), count: cleared) + kept
        return cleared
    }
}

