public final class ScoreLedger: @unchecked Sendable {
    public static let shared = ScoreLedger()

    public private(set) var entries: [Int] = []

    public func record(_ points: Int) {
        entries.append(points)
    }

    public var total: Int { entries.reduce(0, +) }
}

