public actor HighScores {
    private var scores: [Int] = []

    public init() {}

    public func submit(_ score: Int) {
        scores.append(score)
        scores.sort(by: >)
        scores = Array(scores.prefix(10))
    }

    public var best: Int? { scores.first }
}

