import XCTest
@testable import BlockCore

final class BoardTests: XCTestCase {
    func testClearsAFullRow() {
        // Arrange
        var board = Board()
        for column in 0..<Board.width { board.fill(row: 19, column: column) }

        // Act
        let cleared = board.clearFullRows()

        // Assert
        XCTAssertEqual(cleared, 1)
        XCTAssertFalse(board.rows[19].contains(true))
    }
}

import Testing
@testable import BlockCore

struct HighScoresTests {
    @Test(arguments: [[3, 9, 4], [9], [1, 9, 2, 8]])
    func bestIsTheHighestSubmitted(scores: [Int]) async {
        // Arrange
        let highScores = HighScores()
        for score in scores { await highScores.submit(score) }

        // Act
        let best = await highScores.best!

        // Assert
        #expect(best == 9)
    }
}

