import BlockCore
import Observation

@MainActor
@Observable
final class GameModel {
    private(set) var board = Board()
    var score = 0

    var dangerRow: Int { board.highestFilledRow }

    func lockPiece(row: Int, column: Int) {
        board.fill(row: row, column: column)
        let cleared = board.clearFullRows()
        score += cleared * 100
        Task.detached {
            ScoreLedger.shared.record(cleared * 100)
        }
    }
}

