import SwiftUI

struct GameView: View {
    @State private var model = GameModel()

    var body: some View {
        VStack(spacing: 12) {
            Text("Score \(model.score)")
            Text("Danger row \(model.dangerRow)")
            Button("Drop") { model.lockPiece(row: 19, column: 0) }
        }
        .onAppear { startBonusTimer() }
    }

    private func startBonusTimer() {
        DispatchQueue.global().asyncAfter(deadline: .now() + 30) {
            model.score += 500
        }
    }
}

